submit("""CREATE OR REPLACE FUNCTION enforce_inspection_rule()
RETURNS trigger AS $$
BEGIN
    IF NEW.inspect_status = 'Failed' AND NEW.OPER_status <> 'Storage' THEN
        RAISE EXCEPTION 'Equipment cannot be used when inspection has failed.';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER inspection_rule
BEFORE INSERT OR UPDATE ON OperationMaintenance
FOR EACH ROW EXECUTE FUNCTION enforce_inspection_rule();""")

